mapper.select:
SELECT id, user_id, target_type, target_id, rating, content, status, created_at, updated_at
  FROM reviews
 WHERE id = #{id}

SELECT r.id, r.user_id, r.target_type, r.target_id, r.rating, r.content, r.status, r.created_at, r.updated_at, u.nickname AS author_nickname FROM reviews r JOIN users u ON u.id = r.user_id WHERE r.target_type = #{targetType} AND r.target_id = #{targetId} AND r.status = 'VISIBLE' ORDER BY
r.rating DESC, r.created_at DESC, r.id DESC r.rating ASC, r.created_at DESC, r.id DESC r.created_at DESC, r.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
  FROM reviews
 WHERE target_type = #{targetType}
   AND target_id = #{targetId}
   AND status = 'VISIBLE'

SELECT target_type, target_id, review_count, rating_sum, avg_rating
  FROM review_stats
 WHERE target_type = #{targetType}
   AND target_id = #{targetId}

SELECT rating, COUNT(*) AS count
  FROM reviews
 WHERE target_type = #{targetType}
   AND target_id = #{targetId}
   AND status = 'VISIBLE'
 GROUP BY rating

mapper.update:
UPDATE reviews
   SET rating = #{rating},
       content = #{content}
 WHERE id = #{id}

UPDATE reviews
   SET status = 'HIDDEN'
 WHERE id = #{id}
